  const xs = g.pts.map((p) => p[0]), ys = g.pts.map((p) => p[1])
  return { skRefGeo: g, sketchFocus: { c: [(Math.min(...xs) + Math.max(...xs)) / 2, (Math.min(...ys) + Math.max(...ys)) / 2], size: Math.max(Math.max(...xs) - Math.min(...xs), Math.max(...ys) - Math.min(...ys), 20) } }
