  sketchOnAngleDatum: (arb: { o: [number, number, number]; xd: [number, number, number]; n: [number, number, number] }, datumIdx?: number, base?: Plane) => void   // GM-3DV2 R12：datumIdx/base = 关联该 arb datum（datum 郁 → 草图跟）
  removePlane: (i: number) => void
