  edgePtPick: { mode: 'ratio' | 'vertex' | 'mid' | 'pathplane' | 'angleplane' | 'edgeaxis'; ratio: number; dist: number | null; ang?: number } | null   // edgeaxis（S178）= 沿边建構造軸
