  openDxfDialog: () => void
  // GM-X3 #6/#7/#8：opt 可选「入草图源」+ 平面/Z角/缩放/逐层。asSketch=true（默认）→ 生成带 sketchId 的 extrude，可双击时间轴重开改曲线。
  importProfiles2D: (items: { profile: { kind: 'circle'; c: [number, number]; r: number } | { kind: 'poly'; pts: [number, number][] }; operation: 'new' | 'cut'; layer?: string }[], label: string, skipped?: string[], height?: number, opt?: ImportVecOpt) => Promise<void>
  importSvg: (text: string, height?: number, opt?: ImportVecOpt) => Promise<void>
  openSvgDialog: () => void
  // GM-X3 #7/#8：矢量导入对话框（SVG/DXF）—— 平面 / Z角 / 缩放 / (DXF)单位 / 逐层包含 / 入草图源。
  insertVec: null | { kind: 'svg' | 'dxf'; text: string; layers: string[]; include: string[]; plane: Plane; baseZ: number; zAngle: number; scale: number; unit: MeshUnit; height: number; asSketch: boolean; sketchOnly: boolean; forceSketchOnly?: boolean; profileCount?: number; textCount?: number; bytes?: number; parseCache?: { profiles: unknown[]; texts: unknown[]; note: string; skipped: string[]; layers: string[]; stats?: unknown }; importEpoch?: number }
  openInsertVec: (kind: 'svg' | 'dxf', text: string, layers: string[], hint?: { profileCount?: number; textCount?: number; sketchOnly?: boolean; forceSketchOnly?: boolean; bytes?: number; parseCache?: { profiles: unknown[]; texts: unknown[]; note: string; skipped: string[]; layers: string[]; stats?: unknown } }) => void
  /** v1.34: bump to cancel in-flight DXF parse/import */
  dxfImportEpoch: number
  setInsertVec: (p: Partial<NonNullable<AppState['insertVec']>>) => void
  toggleInsertVecLayer: (layer: string) => void
  confirmInsertVec: () => Promise<void>
  cancelInsertVec: () => void
  selectedComponent: string | null
  selectComponent: (id: string | null) => void
  // Browser-level body focus is transient UI state.  The component remains the assembly
  // selection target; this identifies which definition body a later body-safe command targets.
  selectedComponentBody: { componentId: string; bodyId: string } | null
  selectComponentBody: (componentId: string, bodyId: string | null) => void
  compMeasureFrom: string | null
  measureFromComponent: (id: string) => void
  measureTwoComponents: (idA: string, idB: string) => void
  compMeasureSeg: { a: [number, number, number]; b: [number, number, number] } | null   // S124：两件最近点连线（three 世界坐标，蓝虚线 overlay）
  compMateFrom: string | null // C3: pending mate first-pick
  mateType: MateType; mateAxis: MateAxis; mateSide: MateSide; mateDistance: number // mate config (bbox-based)
  setMateConfig: (p: Partial<{ mateType: MateType; mateAxis: MateAxis; mateSide: MateSide; mateDistance: number }>) => void
  mateFromComponent: (id: string) => void
  mateStack: (selId: string, targetId: string) => void
  // Face-pick mate: pick a planar face on part A (reference), then a planar face on part B (moves) → B mates flat.
  faceMateMode: boolean
  faceMatePick: { compId: string; face: MateFace } | null
  faceMatePointPick: { compId: string; point: [number, number, number] } | null
  faceMateFlip: boolean; faceMateGap: number
  setFaceMateOpt: (p: Partial<{ faceMateFlip: boolean; faceMateGap: number }>) => void
  startFaceMate: (oneShot?: boolean) => void
  faceMateOneShot: boolean                                // T776：Align 一次性模式（唔记录持久 mate）
  cancelFaceMate: () => void
  pickFaceForMate: (compId: string, face: MateFace) => void
  pickPointForMate: (compId: string, point: [number, number, number]) => void
