  moveComponentsByUser: (ids: string[], d: [number, number, number], r?: [number, number, number]) => boolean   // ASM2 P2：用戶移動組件（world 位移／旋轉增量）— 尊重關節（見 assembly/componentMove）
  setComponentRot: (id: string, rot: [number, number, number]) => void
