  appChoice: (msg: string, alt: string, title?: string, okLabel?: string) => Promise<'ok' | 'alt' | null>
  /** T3: File ▸ New — 儲存 (save, then new only if the save landed) / 不儲存·Don't Save (discard) / 取消. */
  newFileFlow: () => Promise<void>

