    const ready = s.thickenMode && s.mode === 'model' && !!f && s.features.length > 0 && !thickenOversizeReason(s.bodyMesh, s.thickenThick)
    set({ thickenPreviewMesh: null, thickenPreviewFail: null, thickenPreviewBusy: ready })
