    const c = s.skCons.find((x) => x.id === id)
    if (!c || c.kind !== 'dim' || (c.type !== 'rad' && c.type !== 'dia')) { set({ status: 'R↔Ø：淨是半徑 R / 直徑 Ø 尺寸可以切（右鍵弧/圓尺寸標籤）' }); return }
    const flip = !c.radDiaFlip
