        let sweep = a1 - a0; while (sweep <= -Math.PI) sweep += 2 * Math.PI; while (sweep > Math.PI) sweep -= 2 * Math.PI
        if (Math.abs(sweep) < 0.05) return { sketchStart: null, polyPts: [], status: '中心點圓弧：弧太短 — 終點拉開些' }
        const aEnd = a0 + sweep, aMid = a0 + sweep / 2
