        const B: Pt = [c[0] + R * Math.cos(aEnd), c[1] + R * Math.sin(aEnd)]
        const M: Pt = [c[0] + R * Math.cos(aMid), c[1] + R * Math.sin(aMid)]
        // 同三点弧同款 augmented poly（弓形闭合 — 内核真弧 + 求解器 arc prim）
        const seg = Math.max(8, Math.round(Math.abs(sweep) / 0.12))
