    set({ motionEnvelope: { min: [mn[0], mn[1]], max: [mx[0], mx[1]] }, status: `已算運動包絡 ${(mx[0] - mn[0]).toFixed(0)}×${(mx[1] - mn[1]).toFixed(0)}mm（機構掃一圈占用範圍 — 設計外殼/避讓用）` })
