// Returns a printability warning suffix for an export status line, or '' if the mesh is watertight.
// Non-watertight meshes (open boundary / non-manifold edges) make slicers guess at the interior.
function wtWarn(m?: { vertices: number[]; triangles: number[] } | null): string {
  if (!m || !m.vertices.length || !m.triangles.length) return ''
  const w = meshManifold(m.vertices, m.triangles)
  if (w.closed) return ''
  return `　⚠ 網格非水密（${w.boundary} 開放邊${w.nonManifold ? ' · ' + w.nonManifold + ' 非流形邊' : ''}）—— 切片器可能出錯，建議檢查模型`
}
// Multi-part variant for assembly exports — counts how many parts are not watertight.
function wtWarnParts(meshes: ({ vertices: number[]; triangles: number[] } | null | undefined)[]): string {
  let bad = 0, total = 0
  for (const m of meshes) {
    if (!m || !m.vertices.length || !m.triangles.length) continue
    total++
    if (!meshManifold(m.vertices, m.triangles).closed) bad++
  }
  return bad ? `　⚠ ${bad}/${total} 個零件網格非水密 —— 切片器可能出錯，建議檢查` : ''
}
