if (import.meta.env.DEV) Object.assign(window as unknown as Record<string, unknown>, { useApp, compWorldMatrix, meshCenter3, meshesToGLB, solveLinkage, cad, solveLoop, findLoops, solve4Bar, simulateMotion, buildGroupFK, mateSolve })  // cad（T762）/solveLoop（T774）/simulateMotion（S101[9]）/buildGroupFK（S123）/mateSolve（#13）：e2e 直探

// Only the sketchSources referenced by a live feature — drops orphans left by undo/delete so
// the persisted payload never grows unbounded (review: orphan sketchSources bloat).
// T746：改键 generic f.sketchId（唔再限 extrude）— revolve 等草图特征嘅源唔会畀持久化静默剪走。
function liveSketchSources(s: AppState): AppState['sketchSources'] {
  const live = new Set<string>()
  if (s.skEditTarget) live.add(s.skEditTarget)
  for (const f of s.features) {
    const sk = (f as { sketchId?: string }).sketchId; if (sk) live.add(sk)
    for (const k of (f as { sketchIds?: string[] }).sketchIds ?? []) live.add(k)   // T753：loft 逐截面源
  }
  const out: AppState['sketchSources'] = {}
  for (const k in s.sketchSources) if (live.has(k)) out[k] = s.sketchSources[k]
  return out
}
